import * as T from './vendor/package/build/three.module.js';
export {T};
export const scene=new T.Scene();scene.background=new T.Color('#18263e');scene.fog=new T.FogExp2('#18263e',.018);
export const camera=new T.PerspectiveCamera(48,innerWidth/innerHeight,.1,160);
export const renderer=new T.WebGLRenderer({antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.7));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;renderer.toneMappingExposure=1.25;document.querySelector('#viewport').append(renderer.domElement);
scene.add(new T.HemisphereLight('#d0dffe','#727d72',2.2));let sun=new T.DirectionalLight('#ffe6c2',3.6);sun.position.set(-12,25,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);Object.assign(sun.shadow.camera,{left:-24,right:24,top:24,bottom:-24,near:.5,far:90});sun.shadow.bias=-.001;scene.add(sun);scene.add(new T.AmbientLight('#bf9ae0',.25));
const mats=new Map();export function mat(c,em=0){let key=c+':'+em;if(!mats.has(key))mats.set(key,new T.MeshStandardMaterial({color:c,roughness:.8,metalness:.05,emissive:c,emissiveIntensity:em}));return mats.get(key)}
export function mesh(geo,color,x=0,y=0,z=0,parent=scene,em=0){let m=new T.Mesh(geo,mat(color,em));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
export function box(x,y,z,w,h,d,c,parent=scene){return mesh(new T.BoxGeometry(w,h,d),c,x,y,z,parent)}
export function crystal(x,z,color='#d4bee6',s=1,parent=scene){let m=mesh(new T.OctahedronGeometry(.4*s),color,x,.65*s,z,parent,.3);m.scale.y=1.8;let b=mesh(new T.CylinderGeometry(.5*s,.65*s,.18,6), '#718b8b',x,.05,z,parent);return m}
export function ring(x,z,r=1,c='#e4d4a0'){let m=mesh(new T.TorusGeometry(r,.025,6,48),c,x,.06,z);m.rotation.x=-Math.PI/2;return m}
export let environment=new T.Group();scene.add(environment);export function clearWorld(){scene.remove(environment);environment.traverse(o=>{if(o.geometry)o.geometry.dispose()});environment=new T.Group();scene.add(environment)}
export function terrain(style='garden'){let root=environment;mesh(new T.CylinderGeometry(21,19.5,1.3,64),'#425d66',0,-.8,0,root);mesh(new T.CylinderGeometry(21,21,.18,64),style==='village'?'#708a7c':'#73928c',0,-.08,0,root);let rim=mesh(new T.TorusGeometry(20.4,.12,6,96),'#bdc2a1',0,-.03,0,root);rim.rotation.x=Math.PI/2;
for(let i=0;i<45;i++){let a=i*2.399,r=13+(i%6)*1.1,x=Math.cos(a)*r,z=Math.sin(a)*r; if(style==='village'&&(z>10||Math.abs(x)<10&&Math.abs(z)<14))continue;let trunk=box(x,.55,z,.3,1.2,.3,'#8d7e79',root);let leaves=mesh(new T.IcosahedronGeometry(1.25+(i%3)*.2,0),i%3?'#577c78':'#8ba58a',x,2.1,z,root);leaves.scale.set(.8,1.3,.8);box(x+.1,1.7,z,.12,1.5,.12,'#9c8a7f',root)}
for(let i=0;i<70;i++){let a=i*2.399,r=5+(i%12)*1.15,x=Math.cos(a)*r,z=Math.sin(a)*r;if(style==='village'&&(z>10||Math.abs(x)<10&&Math.abs(z)<14))continue;box(x,.14,z,.05,.3,.05,'#9aaa7e',root);let f=mesh(new T.IcosahedronGeometry(.14,0),i%3?'#e7c7ba':'#f3ddb0',x,.36,z,root)}
for(let i=0;i<8;i++){let a=i/8*Math.PI*2;crystal(Math.cos(a)*17,Math.sin(a)*17,'#a9c2d3',.8,root)}
for(let i=0;i<5;i++){let x=-11+i*1.1;box(x,1.5,-7,.6,3,.7,'#a0aaa0',root);box(x,3,-7,.9,.25,.9,'#c6c7b4',root)}box(-8.8,3.3,-7,5.8,.4,.8,'#bdc1ad',root);
let lake=mesh(new T.CircleGeometry(30,80),'#253f56',0,-2,0,root);lake.rotation.x=-Math.PI/2;let moon=mesh(new T.SphereGeometry(2,24,16),'#f3d9a6',-19,23,-36,root,1);moon.castShadow=false;
}
export function avatar(color='#c6a5bd',male=false){let r=new T.Group(),body=new T.Group();r.add(body);const skin='#edc6ad',hair=male?'#4f4650':'#55465c';let torso=mesh(new T.CylinderGeometry(.23,.32,.56,8),color,0,1.12,0,body);let cloak=mesh(new T.ConeGeometry(.46,.8,8,1,true),color,0,.88,-.07,body);cloak.rotation.x=.08;box(0,1.13,.24,.18,.46,.07,'#e7cf9b',body);
let head=mesh(new T.BoxGeometry(.48,.49,.43),skin,0,1.68,0,body);head.geometry.translate(0,0,0);mesh(new T.SphereGeometry(.34,8,6,0,Math.PI*2,0,Math.PI*.65),hair,0,1.83,-.045,body).scale.set(1,.85,.9);box(-.23,1.68,-.12,.13,male?.32:.7,.32,hair,body);box(.23,1.68,-.12,.13,male?.32:.7,.32,hair,body);box(0,1.88,.15,.5,.12,.18,hair,body);box(-.12,1.69,.222,.045,.066,.012,'#33354a',body);box(.12,1.69,.222,.045,.066,.012,'#33354a',body);box(0,1.55,.225,.08,.018,.012,'#c48f92',body);box(.25,1.84,.1,.1,.09,.08,'#f0d59b',body);
let legs=[],arms=[];for(let sign of [-1,1]){let p=new T.Group();p.position.set(sign*.14,.8,0);body.add(p);box(0,-.28,0,.17,.5,.18,'#45465b',p);box(0,-.54,.05,.2,.15,.3,'#d2b68f',p);legs.push(p);let a=new T.Group();a.position.set(sign*.31,1.33,0);body.add(a);box(sign*.04,-.19,0,.14,.38,.17,color,a);box(sign*.04,-.41,0,.12,.13,.13,skin,a);arms.push(a)}
let sword=new T.Group();sword.position.set(.04,-.39,.02);sword.rotation.z=Math.PI;sword.rotation.x=Math.PI/2;arms[1].add(sword);box(0,.33,0,.055,.8,.1,'#daf3ef',sword);let tip=mesh(new T.ConeGeometry(.075,.18,4),'#e4f8f5',0,.82,0,sword);box(0,-.05,0,.32,.065,.1,'#d9bb8c',sword);box(0,-.16,0,.07,.22,.07,'#726580',sword);
let glow=mesh(new T.TorusGeometry(.24,.018,6,28),'#edcf8f',0,2.2,0,body,.5);glow.rotation.x=Math.PI/2;r.userData={body,legs,arms,sword,glow,cloak,walk:0,swing:0};scene.add(r);return r}
export function animateAvatar(r,dt,speed=0,time=0){let d=r.userData;d.walk+=dt*speed*2.2;d.legs.forEach((l,i)=>l.rotation.x=Math.sin(d.walk+(i?Math.PI:0))*.65*Math.min(speed/4,1));d.arms[0].rotation.x=-Math.sin(d.walk)*.3*Math.min(speed/4,1);d.body.position.y=Math.abs(Math.sin(d.walk))*Math.min(.06,speed*.015);d.swing=Math.max(0,d.swing-dt*3);let t=1-d.swing;let arc=d.swing>0?Math.sin(t*Math.PI):0;d.arms[1].rotation.x=-.1-arc*1.3;d.arms[1].rotation.z=d.swing>0?-.3+Math.sin(t*Math.PI*2)*1.1:-.12;d.arms[1].rotation.y=arc*1.4;d.glow.position.y=2.2+Math.sin(time*2)*.04}
export function shadowEnemy(x,z,color='#9470b8'){let r=new T.Group();r.position.set(x,0,z);scene.add(r);mesh(new T.ConeGeometry(.65,1.8,7),color,0,1.1,0,r);let h=mesh(new T.IcosahedronGeometry(.45,1),'#37334f',0,2,0,r);mesh(new T.ConeGeometry(.14,.55,5),color,-.3,2.4,0,r).rotation.z=.3;mesh(new T.ConeGeometry(.14,.55,5),color,.3,2.4,0,r).rotation.z=-.3;box(-.15,2.02,.39,.1,.055,.03,'#f3c4e8',r);box(.15,2.02,.39,.1,.055,.03,'#f3c4e8',r);let orb=mesh(new T.OctahedronGeometry(.17),'#d9a4e6',0,1.1,.55,r,.5);r.userData={orb};return r}
export function house(x,z,i){let root=new T.Group();root.position.set(x,0,z);environment.add(root);box(0,.03,0,6,.2,6,i%2?'#aa9b90':'#a79e94',root);for(let j=-2;j<3;j++)box(j,.15,0,.025,.02,5.8,'#877f79',root);
box(-3,.7,0,.25,1.5,6.2,'#c2ada2',root);box(3,.7,0,.25,1.5,6.2,'#c2ada2',root);box(0,.7,-3,6,1.5,.25,'#b8a6a0',root);box(-2,.7,3,2,1.5,.25,'#c2ada2',root);box(2,.7,3,2,1.5,.25,'#c2ada2',root);
for(let a of [-3,3])for(let b of [-3,3]){box(a,1.2,b,.3,2.5,.3,'#8c7a78',root);box(a,2.5,b,.45,.15,.45,'#dfc9a8',root)}
// The rear roof is deliberately cut away so the playable interior stays visible.
let roof=box(0,2.4,-2.8,6.7,.16,.8,i%2?'#8e8199':'#8d8e9f',root);roof.rotation.x=.35;box(0,1.55,-3,5.8,.15,.4,'#d1bda0',root);box(-3,1.55,0,.35,.15,6,'#d1bda0',root);box(3,1.55,0,.35,.15,6,'#d1bda0',root);
let pivot=new T.Group();pivot.position.set(-.95,0,3);root.add(pivot);let door=box(.95,.85,0,1.9,1.7,.13,'#947b81',pivot);box(.95,1.55,.1,1.8,.12,.06,'#d4b88d',pivot);box(1.65,.8,.12,.1,.1,.1,'#edcd88',pivot);pivot.rotation.y=-Math.PI*.48;
box(-1.6,.4,-1.2,1.3,.65,2.2,'#766579',root);box(-1.6,.78,-1.2,1.3,.18,2.2,i%2?'#a5b8cb':'#c3a4b4',root);box(-1.6,.9,-1.9,1.13,.18,.6,'#eee3cd',root);box(1.5,.6,-1.9,1.4,1,.8,'#917f7d',root);box(1.5,1.3,-2,.9,.65,.13,'#566378',root);box(1.5,1.3,-1.91,.7,.45,.025,'#b0ddd0',root);mesh(new T.CylinderGeometry(.45,.5,.12,16),'#e4ce9f',0,.2,.6,root);let rug=mesh(new T.CircleGeometry(1.05,32),'#bba7ac',-.6,.16,.3,root);rug.rotation.x=-Math.PI/2;let lamp=mesh(new T.IcosahedronGeometry(.2,1),'#f6dca6',2,1.6,2,root,.7);return{root,pivot,x,z,doorOpen:true,doorAnim:1,hp:120,maxHp:120,level:1,turrets:[],slots:[{x:x+1.8,z:z+.3},{x:x-1.8,z:z+1.5},{x:x+1.8,z:z+1.7}],bed:new T.Vector3(x-1.6,0,z-1.2),computer:new T.Vector3(x+1.5,0,z-1.1),occupied:false,broken:false};}
export function turret(x,z){let r=new T.Group();r.position.set(x,0,z);scene.add(r);mesh(new T.CylinderGeometry(.35,.5,.35,8),'#6e8588',0,.22,0,r);let head=new T.Group();head.position.y=.8;r.add(head);mesh(new T.OctahedronGeometry(.3),'#b2d9d9',0,0,0,head,.3);let barrel=mesh(new T.CylinderGeometry(.09,.12,.65,8),'#e4cda0',0,.04,.35,head);barrel.rotation.x=Math.PI/2;r.userData.head=head;return r}
const effects=[];export function burst(v,color='#f5d69c',count=16){for(let i=0;i<count;i++){let p=mesh(new T.OctahedronGeometry(.055),color,v.x,v.y,v.z,scene,.5);effects.push({p,vel:new T.Vector3((Math.random()-.5)*4,Math.random()*4,(Math.random()-.5)*4),life:.6+Math.random()*.5})}}
export function animateEffects(dt){for(let i=effects.length-1;i>=0;i--){let e=effects[i];e.life-=dt;e.p.position.addScaledVector(e.vel,dt);e.vel.y-=dt*4;e.p.scale.setScalar(Math.max(0,e.life));if(e.life<=0){scene.remove(e.p);e.p.geometry.dispose();effects.splice(i,1)}}}
export function disposeObject(o){scene.remove(o);o.traverse(n=>n.geometry?.dispose())}
export function chestModel(x,z){let r=new T.Group();r.position.set(x,0,z);scene.add(r);box(0,.5,0,1.4,.8,1,'#9a7c91',r);for(let xx of [-.5,.5])box(xx,.5,.51,.1,.8,.06,'#dec48e',r);let lid=new T.Group();lid.position.set(0,.9,-.5);r.add(lid);box(0,.08,.5,1.48,.22,1.06,'#c4a989',lid);box(0,.08,.5,1.2,.23,.8,'#a78b9d',lid);box(0,.7,.55,.18,.22,.08,'#f5dca5',r);r.userData.lid=lid;return r}
export const project=v=>v.clone().project(camera);
addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight)});

export function restPose(r,h){r.position.set(h.bed.x,1.19,h.bed.z+.9);r.rotation.set(0,0,0);let d=r.userData;d.body.rotation.set(-Math.PI/2,0,0);d.body.position.set(0,0,0);d.legs.forEach(l=>l.rotation.set(0,0,0));d.arms.forEach(a=>a.rotation.set(0,0,0));d.sword.visible=false;d.glow.visible=false;d.cloak.visible=false}
